const crypto = require('crypto');
const secret = $env.AUTOMATION_API_SECRET;
const base = ($env.CONVEX_SITE_URL || '').replace(/\/$/, '');
if (!secret || !base) throw new Error('AUTOMATION_API_SECRET and CONVEX_SITE_URL must be set on the n8n container');
// Signature = HMAC-SHA256 over `${unixSeconds}.${METHOD}.${path}.${rawBody}`
const signed = (method, path, body) => {
  const ts = String(Math.floor(Date.now() / 1000));
  const sig = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.${method}.${path}.${body}`).digest('hex');
  return { url: base + path, ts, sig };
};const { execution, workflow } = $input.first().json;
const body = JSON.stringify({
  workflow: String(workflow?.name ?? 'unknown'),
  executionId: String(execution?.id ?? Date.now()),
  message: String(execution?.error?.message ?? 'unknown error').slice(0, 250),
});
console.error(`[lendloop] workflow failed: ${body}`);
return [{ json: { ...signed('POST', '/automation/errors', body), body } }];
